export type CacheEntry<T>={data:T;createdAt:string;expiresAt:string;provider:string;version:string};
export class TtlCache{private items=new Map<string,CacheEntry<unknown>>();set<T>(key:string,data:T,ttlMinutes:number,provider:string,version='1'){const now=Date.now();this.items.set(key,{data,createdAt:new Date(now).toISOString(),expiresAt:new Date(now+ttlMinutes*60_000).toISOString(),provider,version})}get<T>(key:string,maxStaleMinutes=60){const entry=this.items.get(key) as CacheEntry<T>|undefined;if(!entry)return{state:'miss' as const};const age=Date.now()-new Date(entry.expiresAt).getTime();if(age<=0)return{state:'fresh' as const,entry};if(age<=maxStaleMinutes*60_000)return{state:'stale' as const,entry};return{state:'expired' as const}}}
